def maxSumLimitedTurns(grid, t):
    m, n = len(grid), len(grid[0])
    t = min(t, m + n)
    NEG = float("-inf")
    # prev[d][k][c]: d = 0 last step right, d = 1 last step down
    prev = None
    for r in range(m):
        cur = [[[NEG] * n for _ in range(t + 1)] for _ in range(2)]
        for c in range(n):
            v = grid[r][c]
            if r == 0 and c == 0:
                cur[0][0][0] = v
                cur[1][0][0] = v
                continue
            for k in range(t + 1):
                if c > 0:
                    a = cur[0][k][c - 1]
                    if k > 0 and cur[1][k - 1][c - 1] > a:
                        a = cur[1][k - 1][c - 1]
                    cur[0][k][c] = a + v
                if r > 0:
                    b = prev[1][k][c]
                    if k > 0 and prev[0][k - 1][c] > b:
                        b = prev[0][k - 1][c]
                    if b + v > cur[1][k][c]:
                        cur[1][k][c] = b + v
        prev = cur
    return int(max(prev[d][k][n - 1] for d in range(2) for k in range(t + 1)))
